use std::fs

fn parse_num(s: string) -> Option<int> {
    let mut neg = false
    let mut val = 0
    let mut count = 0
    for c in s.chars() {
        if count == 0 && c == '-' {
            neg = true
        } else if c >= '0' && c <= '9' {
            val = val * 10 + (c as int - '0' as int)
        } else {
            return None
        }
        count += 1
    }
    let digits = if neg { count - 1 } else { count }
    if digits == 0 {
        return None
    }
    if neg { Some(0 - val) } else { Some(val) }
}

fn eval(line: string) -> string {
    let mut stack: Vec<int> = []
    for tok in line.split(" ") {
        if tok == "" {
            continue
        }
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if stack.len() < 2 {
                return "error: underflow"
            }
            let b = stack.pop().unwrap_or(0)
            let a = stack.pop().unwrap_or(0)
            if tok == "+" {
                stack.push(a + b)
            } else if tok == "-" {
                stack.push(a - b)
            } else if tok == "*" {
                stack.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                stack.push(a / b)
            }
        } else {
            match parse_num(tok) {
                Some(n) => stack.push(n),
                None => return "error: token",
            }
        }
    }
    if stack.len() != 1 {
        return "error: leftover"
    }
    "${stack[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line.trim()))
    }
}

